package mcp

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	"git-ctx/internal/auth"
)

// The tool answer cache. Its keys fold in the ACL and index state, so a cached
// answer can never outlive the permissions it was computed under.

type cacheEntry struct {
	text    string
	expires time.Time
}

// maxToolCacheEntries is deliberately a hard in-process bound. Cache keys
// include principals, repository restrictions, configuration revisions and
// arguments, so a busy multi-tenant server can otherwise accumulate many
// still-valid entries before their TTLs elapse.
const maxToolCacheEntries = 10000

func (s *Server) cacheKey(ctx context.Context, p auth.Principal, tool string, args map[string]any) string {
	raw, _ := json.Marshal(args)
	principals := principalACLs(p)
	sort.Strings(principals)
	repositories := append([]string(nil), p.AllowedRepositories...)
	sort.Strings(repositories)
	aclRevision := s.aclRevision(ctx, principals)
	configRevision := s.searchConfigRevision(ctx)
	return tool + "|" + strings.Join(principals, ",") + "|" + strings.Join(repositories, ",") + "|" + aclRevision + "|" + configRevision + "|" + string(raw)
}

func (s *Server) searchConfigRevision(ctx context.Context) string {
	rows, err := s.store.DB.QueryContext(ctx, `SELECT category,version FROM system_settings
WHERE category IN ('search','model','vector','opensearch') ORDER BY category`)
	if err != nil {
		return "unavailable"
	}
	defer rows.Close()
	digest := sha256.New()
	for rows.Next() {
		var category string
		var version int
		if rows.Scan(&category, &version) == nil {
			_, _ = fmt.Fprintf(digest, "%s:%d\n", category, version)
		}
	}
	return hex.EncodeToString(digest.Sum(nil))
}

func (s *Server) aclRevision(ctx context.Context, principals []string) string {
	if len(principals) == 0 {
		return "none"
	}
	placeholders := make([]string, len(principals))
	args := make([]any, 0, len(principals))
	for index, principal := range principals {
		placeholders[index] = "?"
		args = append(args, principal)
	}
	query := `SELECT p.repository_id,p.principal,p.permission,COALESCE(CAST(r.indexed_at AS TEXT),'')
FROM repository_permissions p JOIN repositories r ON r.id=p.repository_id
WHERE p.principal IN (` + strings.Join(placeholders, ",") + `) OR p.principal='*'
ORDER BY p.repository_id,p.principal`
	rows, err := s.store.DB.QueryContext(ctx, s.store.Rebind(query), args...)
	if err != nil {
		return "unavailable"
	}
	defer rows.Close()
	digest := sha256.New()
	for rows.Next() {
		var repositoryID, principal, permission, indexedAt string
		if rows.Scan(&repositoryID, &principal, &permission, &indexedAt) == nil {
			_, _ = fmt.Fprintf(digest, "%s\x00%s\x00%s\x00%s\n", repositoryID, principal, permission, indexedAt)
		}
	}
	return hex.EncodeToString(digest.Sum(nil))
}
func (s *Server) cached(key string) (string, bool) {
	s.cacheMu.Lock()
	defer s.cacheMu.Unlock()
	entry, ok := s.cache[key]
	if !ok {
		return "", false
	}
	if !time.Now().Before(entry.expires) {
		delete(s.cache, key)
		return "", false
	}
	return entry.text, true
}

func (s *Server) deleteExpiredCacheEntriesLocked(now time.Time) {
	for key, entry := range s.cache {
		if !now.Before(entry.expires) {
			delete(s.cache, key)
		}
	}
}

// trimCacheLocked removes entries that will expire soonest. Choosing the key
// lexicographically when expirations tie makes eviction deterministic without
// maintaining a second unbounded ordering structure. In normal operation this
// loop removes one entry; the loop also repairs a map left above the limit by
// an older server version.
func (s *Server) trimCacheLocked(limit int) {
	for len(s.cache) > limit {
		victimKey := ""
		var victimExpiry time.Time
		for key, entry := range s.cache {
			if victimKey == "" || entry.expires.Before(victimExpiry) ||
				(entry.expires.Equal(victimExpiry) && key < victimKey) {
				victimKey = key
				victimExpiry = entry.expires
			}
		}
		delete(s.cache, victimKey)
	}
}

func (s *Server) storeCache(ctx context.Context, tool, key, text string) {
	var seconds int
	if err := s.store.DB.QueryRowContext(ctx, s.store.Rebind(`SELECT cache_seconds FROM mcp_tools WHERE name=?`), tool).Scan(&seconds); err != nil || seconds <= 0 {
		return
	}
	now := time.Now()
	s.cacheMu.Lock()
	defer s.cacheMu.Unlock()
	if len(s.cache) >= maxToolCacheEntries {
		s.deleteExpiredCacheEntriesLocked(now)
	}

	// Updating an existing entry needs no spare slot. A new key reserves one
	// before insertion so the map never transiently exceeds the hard limit.
	limit := maxToolCacheEntries
	if _, exists := s.cache[key]; !exists {
		limit--
	}
	s.trimCacheLocked(limit)
	s.cache[key] = cacheEntry{text: text, expires: now.Add(time.Duration(seconds) * time.Second)}
}
package mcp

import (
	"fmt"
	"strconv"
	"strings"
)

// Response budgeting. An answer is cut at a section or line boundary so a
// truncated reply still reads as the document it was.

const (
	// DefaultResponseBytes bounds one tool answer when the operator set no
	// per-tool budget. Roughly six thousand tokens: large enough for a full
	// search page, small enough to leave the agent room to work.
	DefaultResponseBytes = 24 << 10
	// MinResponseBytes keeps a budget from becoming a header with no content.
	MinResponseBytes = 2000
	// MaxResponseBytes is the ceiling an operator or caller may raise a tool to.
	MaxResponseBytes = 256 << 10
)

// clampResponse trims one answer to the byte budget without hiding that it did
// so. Two properties matter for an agent reading the result:
//
//   - the cut lands on a result boundary, so the last entry is whole rather than
//     ending mid-line, and
//   - the trailing Notes section survives, because that is where the tool
//     explains which retrieval path ran and what the ACL filtered. Losing it
//     would turn "indexing, answered live" into an unexplained short answer.
func clampResponse(text string, budget int) string {
	if budget <= 0 || len(text) <= budget {
		return text
	}
	body, notes := text, ""
	if at := strings.LastIndex(text, "\n### Notes\n"); at >= 0 {
		body, notes = text[:at], text[at:]
	}
	// The notes only keep their reservation while they stay a small part of the
	// budget; an oversized tail would leave no room for actual results.
	reserved := len(notes)
	if reserved > budget/3 {
		body, notes, reserved = text, "", 0
	}
	total := sectionCount(body)
	room := budget - reserved - responseNoticeBytes
	if room < MinResponseBytes/2 {
		room = budget / 2
	}
	kept := cutAtBoundary(body, room)
	shown := sectionCount(kept)
	notice := fmt.Sprintf("\n\n### Truncated\n- This answer was cut to the %s byte budget of this tool; %s bytes were produced.\n",
		thousands(budget), thousands(len(text)))
	if total > 0 {
		notice += fmt.Sprintf("- %d of %d result sections are included. The rest are not lost, only unsent.\n", shown, total)
	}
	notice += "- Narrow the next call instead of retrying the same one: add libraryId or path, lower limit, or read a line range with read-file.\n"
	return closeOpenFence(strings.TrimRight(kept, "\n")) + notice + notes
}

func boolInt(value bool) int {
	if value {
		return 1
	}
	return 0
}

// responseNoticeBytes reserves room for the truncation notice itself, so adding
// it can never push the answer back over the budget.
const responseNoticeBytes = 320

// sectionCount counts the result entries of a formatted answer. The formatters
// use a `### ` heading per result, and the list formatters use a `- ` item.
func sectionCount(text string) int {
	if count := strings.Count(text, "\n### "); count > 0 {
		return count
	}
	return strings.Count(text, "\n- ")
}

// cutAtBoundary keeps as much of the answer as the room allows, ending it
// somewhere a reader can see the seam.
//
// Every candidate boundary has to keep most of the room, which the paragraph
// and line rules used to skip. A file with no blank line after its first few —
// a minified bundle, a CSV, densely packed code — has its last "\n\n" right
// before the content starts, and cutting there returned a header and nothing
// else: read-file asked for twelve thousand bytes and answered with six
// hundred, while the notice said the answer had been cut to the budget.
func cutAtBoundary(text string, limit int) string {
	if limit >= len(text) {
		return text
	}
	window := text[:limit]
	enough := func(at int) bool { return at > 0 && at*10 >= limit*6 }
	if at := strings.LastIndex(window, "\n### "); enough(at) {
		return text[:at]
	}
	if at := strings.LastIndex(window, "\n\n"); enough(at) {
		return text[:at]
	}
	if at := strings.LastIndexByte(window, '\n'); enough(at) {
		return text[:at]
	}
	return runeSafeCut(window, len(window))
}

// closeOpenFence terminates a code fence the cut landed inside. Without it the
// notice explaining the truncation, and the notes after it, are read as part of
// the file that was being shown.
func closeOpenFence(text string) string {
	if strings.Count(text, "\n```")%2 == 0 && !strings.HasPrefix(text, "```") {
		return text
	}
	if strings.Count(text, "```")%2 == 0 {
		return text
	}
	return text + "\n```"
}

// thousands formats a byte count the way the notice reads best.
func thousands(value int) string {
	digits := strconv.Itoa(value)
	var b strings.Builder
	for index, char := range digits {
		if index > 0 && (len(digits)-index)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(char)
	}
	return b.String()
}
package mcp

import (
	"strings"
	"testing"
	"unicode/utf8"
)

// A truncated answer has to be most of the budget it says it was cut to.
//
// The cut prefers a boundary a reader can see — a section start, a paragraph,
// a line — but the paragraph and line rules took whatever they found. A file
// with no blank line after its first few, which is every minified bundle, CSV
// and densely packed source file, has its last blank line right before the
// content begins. Cutting there answered a twelve-thousand-byte request with
// six hundred bytes: a header, and a notice saying the answer had been cut to
// the budget.
func TestATruncatedAnswerUsesTheBudgetItWasGiven(t *testing.T) {
	var dense strings.Builder
	dense.WriteString("## internal/settlement/big.go\n\n`/gitlab~core/api` · ref `main`\n\n```go\n")
	for i := 0; i < 400; i++ {
		dense.WriteString("func handler(order Order) error { return reconcile(order) }  // 정산 처리\n")
	}
	dense.WriteString("```\n\n### Notes\n- index: reassembled from the stored chunks of this ref.\n")
	answer := dense.String()

	for _, budget := range []int{3000, 8000, 12000, 20000} {
		cut := clampResponse(answer, budget)
		if len(cut) > budget+responseNoticeBytes {
			t.Errorf("budget %d produced %d bytes", budget, len(cut))
		}
		if len(answer) > budget && len(cut)*10 < budget*6 {
			t.Errorf("budget %d was answered with %d bytes; most of what was asked for was thrown away to find a prettier boundary",
				budget, len(cut))
		}
		if !utf8.ValidString(cut) {
			t.Errorf("budget %d cut through a character", budget)
		}
		// The notice and the notes must not end up inside the code block.
		if strings.Count(cut, "```")%2 != 0 {
			t.Errorf("budget %d left the code fence open, so everything after it reads as file content:\n%s",
				budget, cut[max(0, len(cut)-200):])
		}
		if len(answer) > budget && !strings.Contains(cut, "### Truncated") {
			t.Errorf("budget %d cut the answer without saying so", budget)
		}
		if !strings.Contains(cut, "### Notes") {
			t.Errorf("budget %d dropped the notes", budget)
		}
	}
}

// An answer made of result sections still ends on a section, so the last result
// is whole — as long as that keeps most of the room.
func TestASectionedAnswerStillEndsOnASection(t *testing.T) {
	var results strings.Builder
	results.WriteString("## Code Search\n\nNormalized query: `settleInvoice`\n")
	for i := 0; i < 40; i++ {
		results.WriteString("\n### /gitlab~core/api · internal/settlement/handler.go\n\nfunc settleInvoice(order Order) error { return reconcile(order) }\n\nSource: gitlab://core/api@c0ffee/internal/settlement/handler.go#L1-L9\n")
	}
	results.WriteString("\n### Notes\n- acl: unrestricted.\n")
	answer := results.String()

	cut := clampResponse(answer, 4000)
	body := cut[:strings.Index(cut, "### Truncated")]
	if !strings.HasSuffix(strings.TrimRight(body, "\n"), "#L1-L9") {
		t.Errorf("the answer does not end on a whole result:\n%s", body[max(0, len(body)-200):])
	}
	if !strings.Contains(cut, "result sections are included") {
		t.Error("the notice does not say how many results were sent")
	}
}

package mcp

import (
	"context"
	"fmt"
	"sync"
	"testing"
	"time"
)

func enableToolCache(t *testing.T, server *Server) {
	t.Helper()
	if _, err := server.store.DB.Exec(`UPDATE mcp_tools SET cache_seconds=7200 WHERE name='resolve-library-id'`); err != nil {
		t.Fatal(err)
	}
}

func TestToolCacheHardLimitEvictsDeterministically(t *testing.T) {
	server := fixture(t)
	enableToolCache(t, server)
	expires := time.Now().Add(time.Hour)
	// Seed above the new limit to model a process that accumulated entries
	// under the previous implementation before this version took over.
	for index := 0; index < maxToolCacheEntries+1; index++ {
		key := fmt.Sprintf("entry-%05d", index)
		server.cache[key] = cacheEntry{text: key, expires: expires}
	}

	server.storeCache(context.Background(), "resolve-library-id", "new-entry", "new")

	server.cacheMu.Lock()
	defer server.cacheMu.Unlock()
	if got := len(server.cache); got != maxToolCacheEntries {
		t.Fatalf("cache size=%d, want hard limit %d", got, maxToolCacheEntries)
	}
	if _, exists := server.cache["entry-00000"]; exists {
		t.Fatal("lexicographically first key with the same expiry was not evicted")
	}
	if _, exists := server.cache["entry-00001"]; exists {
		t.Fatal("cache inherited above the limit was not fully trimmed")
	}
	if entry, exists := server.cache["new-entry"]; !exists || entry.text != "new" {
		t.Fatalf("new cache entry=%+v exists=%v", entry, exists)
	}
}

func TestToolCachePurgesExpiredEntriesBeforeLiveEntries(t *testing.T) {
	server := fixture(t)
	enableToolCache(t, server)
	now := time.Now()
	for index := 0; index < maxToolCacheEntries-1; index++ {
		key := fmt.Sprintf("live-%05d", index)
		server.cache[key] = cacheEntry{text: key, expires: now.Add(time.Hour)}
	}
	server.cache["expired"] = cacheEntry{text: "stale", expires: now.Add(-time.Second)}

	server.storeCache(context.Background(), "resolve-library-id", "new-entry", "new")

	server.cacheMu.Lock()
	if got := len(server.cache); got != maxToolCacheEntries {
		server.cacheMu.Unlock()
		t.Fatalf("cache size=%d, want %d after expiry cleanup", got, maxToolCacheEntries)
	}
	_, expiredExists := server.cache["expired"]
	_, liveExists := server.cache["live-00000"]
	server.cacheMu.Unlock()
	if expiredExists {
		t.Fatal("expired entry survived cache cleanup")
	}
	if !liveExists {
		t.Fatal("a live entry was evicted even though an expired slot was available")
	}
	if _, ok := server.cached("expired"); ok {
		t.Fatal("expired entry was returned as a cache hit")
	}
}

func TestToolCacheConcurrentAccessStaysBounded(t *testing.T) {
	server := fixture(t)
	enableToolCache(t, server)
	expires := time.Now().Add(time.Hour)
	for index := 0; index < maxToolCacheEntries-20; index++ {
		key := fmt.Sprintf("seed-%05d", index)
		server.cache[key] = cacheEntry{text: key, expires: expires}
	}

	var workers sync.WaitGroup
	for worker := 0; worker < 8; worker++ {
		worker := worker
		workers.Add(1)
		go func() {
			defer workers.Done()
			for index := 0; index < 10; index++ {
				key := fmt.Sprintf("worker-%02d-%02d", worker, index)
				server.storeCache(context.Background(), "resolve-library-id", key, key)
				_, _ = server.cached(key)
			}
		}()
	}
	workers.Wait()

	server.cacheMu.Lock()
	defer server.cacheMu.Unlock()
	if got := len(server.cache); got > maxToolCacheEntries {
		t.Fatalf("cache size=%d exceeds hard limit %d", got, maxToolCacheEntries)
	}
}
package mcp

import (
	"context"
	"time"

	"git-ctx/internal/auth"
)

// Per-tool policy: whether this caller may see a tool, and the limits it runs
// under. The tool entry carries the rules; this file applies them.

func (s *Server) toolVisible(ctx context.Context, p auth.Principal, entry *tool) bool {
	if s.strictMode != nil && s.strictMode(ctx) && !entry.core {
		return false
	}
	if !s.toolEnabled(ctx, entry.name) {
		return false
	}
	if !entry.allowed(p) {
		return false
	}
	return p.KeyID == "" || contains(p.Scopes, entry.name)
}

func (s *Server) toolEnabled(ctx context.Context, name string) bool {
	var enabled int
	if err := s.store.DB.QueryRowContext(ctx, s.store.Rebind(`SELECT enabled FROM mcp_tools WHERE name=?`), name).Scan(&enabled); err != nil {
		return true
	}
	return enabled == 1
}
func (s *Server) toolTimeout(ctx context.Context, name string) time.Duration {
	var timeout int
	if err := s.store.DB.QueryRowContext(ctx, s.store.Rebind(`SELECT timeout_ms FROM mcp_tools WHERE name=?`), name).Scan(&timeout); err != nil || timeout < 100 {
		return 30 * time.Second
	}
	return time.Duration(timeout) * time.Millisecond
}

// responseBudget is the byte budget for one answer of this tool.
func (s *Server) responseBudget(ctx context.Context, name string) int {
	var budget int
	if err := s.store.DB.QueryRowContext(ctx, s.store.Rebind(`SELECT max_response_bytes FROM mcp_tools WHERE name=?`), name).Scan(&budget); err != nil || budget <= 0 {
		return DefaultResponseBytes
	}
	return min(max(budget, MinResponseBytes), MaxResponseBytes)
}
